/*! tailwindcss v4.3.2 | MIT License | https://tailwindcss.com */
.not-sr-only {
  position: static;
  width: auto;
  height: auto;
  padding: 0;
  margin: 0;
  overflow: visible;
  clip-path: none;
  white-space: normal;
}
.-order-1 {
  order: calc(1 * -1);
}
.order-0 {
  order: 0;
}
.order-1 {
  order: 1;
}
.order-first {
  order: -9999;
}
.order-last {
  order: 9999;
}
.order-none {
  order: 0;
}
.contents {
  display: contents;
}
.flow-root {
  display: flow-root;
}
.inline-table {
  display: inline-table;
}
.list-item {
  display: list-item;
}
.table {
  display: table;
}
.table-caption {
  display: table-caption;
}
.table-cell {
  display: table-cell;
}
.table-column {
  display: table-column;
}
.table-column-group {
  display: table-column-group;
}
.table-footer-group {
  display: table-footer-group;
}
.table-header-group {
  display: table-header-group;
}
.table-row {
  display: table-row;
}
.table-row-group {
  display: table-row-group;
}
.basis-1\/2 {
  flex-basis: calc(1 / 2 * 100%);
}
.basis-auto {
  flex-basis: auto;
}
.basis-full {
  flex-basis: 100%;
}
.basis-px {
  flex-basis: 1px;
}
.appearance-auto {
  appearance: auto;
}
.appearance-none {
  appearance: none;
}
.fill-current {
  fill: currentcolor;
}
.fill-none {
  fill: none;
}
.stroke-current {
  stroke: currentcolor;
}
.stroke-none {
  stroke: none;
}
.stroke-0 {
  stroke-width: 0;
}
.stroke-1 {
  stroke-width: 1;
}
